package com.hbm.machine.pa.cooled;
import api.hbm.redstoneoverradio.IRORInteractive;
import com.hbm.api.computer.*;
import com.hbm.machine.pa.parts.PaCoilItem;
import com.hbm.machine.pa.physics.*;
import com.hbm.world.structure.generated.compat.ForgeDirection;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.block.state.BlockState;
public final class PaDipoleEntity extends PaCooledEntity implements PaParticleUser,IRORInteractive {
 public static final long USAGE=100000;public int dirLower,dirUpper,dirRedstone,threshold;
 public PaDipoleEntity(BlockPos pos,BlockState state){super(PaContent.ENTITY.get(),PaKind.DIPOLE,pos,state);}
 public static ForgeDirection direction(int value){return switch(value){case 1->ForgeDirection.EAST;case 2->ForgeDirection.SOUTH;case 3->ForgeDirection.WEST;default->ForgeDirection.NORTH;};}public static String name(int value){return direction(value).name().toLowerCase(Locale.ROOT);}public static int direction(String value){return switch(value){case "north"->0;case "east"->1;case "south"->2;case "west"->3;default->-1;};}
 public boolean redstone(){if(level==null)return false;for(var port:ports())if(level.hasNeighborSignal(port.position().relative(port.side())))return true;return false;}public ForgeDirection exitDirection(PaParticle particle){return direction(particle.momentum<threshold?dirLower:redstone()?dirRedstone:dirUpper);}
 @Override public boolean canParticleEnter(PaParticle particle,ForgeDirection dir,int x,int y,int z){return worldPosition.getY()==y&&(worldPosition.getX()==x||worldPosition.getZ()==z);}
 @Override public void onEnter(PaParticle particle,ForgeDirection dir){var coil=slots[1].getItem() instanceof PaCoilItem item?item.coil(slots[1]):null;boolean inline=dir==exitDirection(particle);int mult=1;if(coil!=null){if(coil.diMin>particle.momentum)mult*=10;if(coil.diDistMin>particle.distanceTraveled)mult*=10;if(inline)mult=1;}if(!isCool())particle.crash(PaState.CRASH_NOCOOL);if(!hasPower(USAGE*mult))particle.crash(PaState.CRASH_NOPOWER);if(coil==null)particle.crash(PaState.CRASH_NOCOIL);if(coil!=null&&coil.diMax<particle.momentum&&!inline)particle.crash(PaState.CRASH_OVERSPEED);if(particle.invalid)return;if(inline)particle.addDistance(3);else particle.resetDistance();usePower(USAGE*mult);}
 @Override public BlockPos getExitPos(PaParticle particle){particle.dir=exitDirection(particle);return worldPosition.offset(particle.dir.offsetX*2,0,particle.dir.offsetZ*2);}
 @Override public void control(CompoundTag tag){if(tag.contains("lower"))dirLower++;if(tag.contains("upper"))dirUpper++;if(tag.contains("redstone"))dirRedstone++;if(tag.contains("threshold"))threshold=tag.getInt("threshold");if(dirLower>3)dirLower-=4;if(dirUpper>3)dirUpper-=4;if(dirRedstone>3)dirRedstone-=4;threshold=Math.clamp(threshold,0,999999999);setChanged();}
 @Override protected void writeState(CompoundTag tag,HolderLookup.Provider lookup){writeSnapshot(tag);}@Override protected void readState(CompoundTag tag,HolderLookup.Provider lookup){readSnapshot(tag);}@Override protected void writeSnapshot(CompoundTag tag){tag.putInt("dirLower",dirLower);tag.putInt("dirUpper",dirUpper);tag.putInt("dirRedstone",dirRedstone);tag.putInt("threshold",threshold);}@Override protected void readSnapshot(CompoundTag tag){dirLower=tag.getInt("dirLower");dirUpper=tag.getInt("dirUpper");dirRedstone=tag.getInt("dirRedstone");threshold=tag.getInt("threshold");}
 @Override public String[] computerMethods(){return new String[]{"getEnergyInfo","getCoolant","getDirLower","setDirLower","getDirUpper","setDirUpper","getDirRedstone","setDirRedstone","getThreshold","setThreshold","getInfo"};}
 @Override public Object[] callComputer(String method,ComputerArguments args){return switch(method){case "getDirLower"->new Object[]{name(dirLower)};case "getDirUpper"->new Object[]{name(dirUpper)};case "getDirRedstone"->new Object[]{name(dirRedstone)};case "setDirLower","setDirUpper","setDirRedstone"->{int dir=direction(args.checkString(0));if(dir>=0){if(method.equals("setDirLower"))dirLower=dir;else if(method.equals("setDirUpper"))dirUpper=dir;else dirRedstone=dir;setChanged();}yield new Object[0];}case "getThreshold"->new Object[]{threshold};case "setThreshold"->{threshold=Math.clamp(args.checkInteger(0),0,999999999);setChanged();yield new Object[0];}case "getInfo"->{var values=new ArrayList<>(Arrays.asList(basicInfo()));values.addAll(List.of(name(dirLower),name(dirUpper),name(dirRedstone),threshold));yield values.toArray();}default->super.callComputer(method,args);};}
 @Override public String[] getFunctionInfo(){return new String[]{PREFIX_VALUE+"temperature",PREFIX_VALUE+"pfmcold",PREFIX_VALUE+"pfm",PREFIX_FUNCTION+"setthreshold"+NAME_SEPARATOR+"threshold"};}@Override public String runRORFunction(String name,String[] params){if(name.equals(PREFIX_FUNCTION+"setthreshold")&&params.length>0){threshold=IRORInteractive.parseInt(params[0],0,999999999);setChanged();}return null;}
}
